script:
frappe.ui.form.on("Vendor Onboarding Request", {
	refresh(frm) {
		function render_pipeline_progress(stages) {
			const color_map = { "Not Started": "gray", "In Progress": "orange", "Completed": "green" };
			const html = stages
				.map(
					(s) =>
						`<span class="indicator-pill ${color_map[s.state] || "gray"}" style="margin-right: 8px;">${frappe.utils.escape_html(s.label)}: ${frappe.utils.escape_html(s.state)}</span>`
				)
				.join("");
			const field = frm.get_field("pipeline_progress");
			if (field) {
				field.html(html);
			}
		}

		function add_accept_reject_buttons(has_kyc) {
			// Locked once a Vendor KYC exists for this request — see
			// _enforce_review_decision_open() in the controller.
			if (has_kyc) {
				return;
			}
			if (frm.doc.status !== "Accepted") {
				frm.add_custom_button(__("Accept"), () => {
					frm.call("accept").then(() => frm.reload_doc());
				});
			}
			if (frm.doc.status !== "Rejected") {
				frm.add_custom_button(__("Reject"), () => {
					frm.call("reject").then(() => frm.reload_doc());
				});
			}
		}

		if (frm.doc.__islocal) {
			return;
		}

		if (frm.doc.status === "Draft") {
			add_accept_reject_buttons(false);
			return;
		}

		frm.call("get_pipeline_progress").then((r) => {
			const stages = r.message || [];
			render_pipeline_progress(stages);

			const kyc_stage = stages.find((s) => s.label === "KYC");
			const has_kyc = !!kyc_stage && kyc_stage.state !== "Not Started";

			add_accept_reject_buttons(has_kyc);

			if (frm.doc.status !== "Accepted") {
				return;
			}

			const handling = frappe.boot.vendor_lifecycle_settings?.duplicate_kyc_handling || "Stop";
			if (has_kyc && handling === "Stop") {
				return;
			}

			frm.add_custom_button(__("Start KYC"), () => {
				frm.call("start_kyc").then((res) => {
					if (res.message) {
						// Opens a fresh, unsaved Vendor KYC form pre-filled with
						// this data — nothing is created until the reviewer saves
						// it themselves.
						frappe.new_doc("Vendor KYC", res.message);
					}
				});
			});
		});
	},
});

frappe.ui.form.on("Vendor Sampling Evaluation", {
	refresh(frm) {
		if (frm.doc.evaluation_template) {
			frm.add_custom_button(__("Load Evaluation from Template"), () => {
				frm.call("load_evaluation_from_template").then(() => frm.refresh());
			});
		}
	},
});

frappe.ui.form.on("Vendor KYC", {
	refresh(frm) {
		if (frm.doc.country === "India" && frm.doc.gstin_uin) {
			frm.add_custom_button(__("Fetch Address from GSTIN"), () => {
				frm.call("fetch_gstin_details").then((r) => {
					frm.refresh_field("gstin_address_line");
					frm.refresh_field("gstin_city");
					frm.refresh_field("gstin_state");
					frm.refresh_field("gstin_pincode");
					if (r.message) {
						frappe.show_alert(
							{
								message: __("Fetched from GSTIN — review the Address Verification section below."),
								indicator: "green",
							},
							7
						);
					}
				});
			});
		}

		if (frm.doc.gstin_address_line || frm.doc.gstin_city) {
			frm.add_custom_button(__("Address Same as GSTIN"), () => {
				frappe.confirm(__("Copy the GSTIN-registered address into the Address fields above?"), () => {
					frm.set_value("firm_address", frm.doc.gstin_address_line);
					frm.set_value("city", frm.doc.gstin_city);
					frm.set_value("state", frm.doc.gstin_state);
					frm.set_value("pincode", frm.doc.gstin_pincode);
					frm.set_value("country", "India");
				});
			});
		}
	},
});
